    }
    )
    }
    

    
    /**
     * Whether keys are still held (false once closed: zeroised).
     */override fun `hasKeys`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_dragent_e2ee_ffi_fn_method_channel_has_keys(
        it,
        _status)
