    }
    )
    }
    

    
    /**
     * Whether [`Channel::quiesce`] was called.
     */override fun `isQuiesced`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_dragent_e2ee_ffi_fn_method_channel_is_quiesced(
        it,
        _status)
