    }
    )
    }
    

    
    /**
     * The last counter sent (`None` if nothing was sent).
     */override fun `lastSentCtr`(): kotlin.ULong? {
            return FfiConverterOptionalULong.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
