/**
 * @suppress
 */
public object FfiConverterTypeChannel: FfiConverter<Channel, Long> {
    override fun lower(value: Channel): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Channel {
        return Channel(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Channel {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Channel) = 8UL

    override fun write(value: Channel, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


